/**
 * S500L040LIGA: fachada que controla el enlace con S500L039BD04, la librería que consulta
 * las relaciones contrato-tarjeta y tarjeta-TEF del sistema S500.
 *
 * SHARING = PRIVATE: cada programa que la llama recibe su propia instancia. En Spring el
 * equivalente más cercano es un bean prototype por consumidor; se usa singleton porque la
 * fachada no guarda estado de negocio, solo el interruptor de enlace.
 */
@Service
@RequiredArgsConstructor
public class LigasFacade implements LigasApi {

    private final LigasL039Client l039;                          // antes LIBRARY LIGACALL
    private final AtomicBoolean ligaActiva = new AtomicBoolean(); // B_LLAMAL039
    public static final int SIN_LIGA = 99;                        // resultado cuando la liga está suspendida
}

/** Misma interfaz que exportaba L040; cada método devuelve el código de resultado de L039. */
public interface LigasApi {
    int fechaS111(byte[] salida);                         // S500L040_FECHA_S111
    int dameTarjeta(byte[] entrada, byte[] salida);       // S500L040_DAME_TARJETA
    int dameContrato(byte[] entrada, byte[] salida);      // S500L040_DAME_CONTRATO
    int dameTef(byte[] entrada, byte[] salida);           // S500L040_DAME_TEF
    int dameCtaOrig(byte[] entrada, byte[] salida);       // S500L040_DAME_CTAORIG
    int dameCtaGlb(byte[] entrada, byte[] salida);        // S500L040_DAME_CTAGLB
    int archDisp(byte[] entrada, byte[] salida);          // S500L040_ARCHDISP  (sincronización S500-S016)
    int camBase(byte[] entrada);                          // S500L040_CAMBASE   (sincronización S500-S016)
    int conInfoCte(byte[] entrada, byte[] salida);        // S500L040_CONINFOCTE
}

/** Cliente de la librería real (antes LIBRARY LIGACALL con los procedimientos *_C). */
public interface LigasL039Client {
    int fechaS111(byte[] salida);
    int dameTarjeta(byte[] entrada, byte[] salida);
    int dameContrato(byte[] entrada, byte[] salida);
    // ... uno por cada procedimiento *_C importado
    void levanta();                                       // S500L040_99_LEVANTA_C
}

/** S500L040_DAME_TARJETA: si la liga está suspendida, devuelve 99 sin llamar a L039. */
@Override
public int dameTarjeta(byte[] entrada, byte[] salida) {
    return ligaActiva.get() ? l039.dameTarjeta(entrada, salida) : SIN_LIGA;
}

// Los otros ocho procedimientos repiten exactamente el mismo patrón. Con Resilience4j se
// puede expresar como un CircuitBreaker forzado a OPEN por el operador:
//   circuitBreaker.transitionToForcedOpenState();   // equivale a HI 1
//   circuitBreaker.transitionToClosedState();       // equivale a HI 2

private final ControlVersiones ctlvers;        // LIBRARY CTLVER BYFUNCTION "CTLVERS"
private final Environment env;

/** CHECA_VERSION: la librería debe estar registrada como S500L040LIGA versión 25MTP002. */
void checaVersion() {
    boolean exento = props.hostsSinValidacion()                   // [ACYPBETA]
            .contains(env.getRequiredProperty("ligas.host"));
    if (!exento && ctlvers.checame("S500L040LIGA", "25MTP002") < 0) {
        lj.error("E>050110<", "ERROR MI NOMBRE NO CORRESP. AL DE CTLVER");
        throw new IllegalStateException("Versión no registrada en CTLVERS");   // MYSELF.STATUS := -1
    }
}

/** PROC_LEVANTA: valida versión, enciende la liga, resuelve el título de L039 y la levanta. */
@PostConstruct
void levanta() {
    checaVersion();
    ligaActiva.set(true);                                 // B_LLAMAL039 := TRUE
    resuelveDestinoL039();                                // PROC_DAME_TIT_S500L039
    l039.levanta();                                       // S500L040_99_LEVANTA_C
}

private void resuelveDestinoL039() {
    ctlvers.dameTitulo("S500L039BD04")
           .ifPresentOrElse(l039::apuntaA,                // REPLACE LIGACALL.TITLE BY EA_TIT FOR 72
                () -> {
                    lj.aviso("L>020901<", "ERROR CALL CTLVER S500L039BD04");
                    ligaActiva.set(false);                // nuevo: no dejar la liga encendida sin destino
                });
}

@Component
@Endpoint(id = "ligas")
@RequiredArgsConstructor
public class LigasAdminEndpoint {

    private final LigasFacade fachada;

    @ReadOperation                                         // HI 3: STATUS ACCESO A L039
    public String estado() {
        return "STATUS ACCESO A L039: " + (fachada.ligaActiva() ? "CON" : "SIN");
    }

    @WriteOperation
    @PreAuthorize("hasRole('OPERADOR_S500')")
    public String hi(@Selector int valor) {
        return switch (valor) {
            case 1 -> { fachada.suspendeLiga();  yield "SE SUSPENDE LIGA A L039"; }  // DELINKLIBRARY
            case 2 -> { fachada.restableceLiga(); yield "SE HACE LIGA A L039"; }      // título + LEVANTA_C
            case 4 -> { fachada.baja();           yield "DESABILITA S500L040LIGA"; }  // GOINGAWAY
            default -> " 1: SUSPENDE LIGA, 2: REALIZA LIGA, 3: ESTATUS, 4: DESABILITA, 99: LISTA";
        };
    }
}
// El ciclo WAITANDRESET((2), EXCEPTIONEVENT) y la salida cuando LIBRARYUSERS = 0 los
// reemplaza el ciclo de vida del contenedor: el bean vive mientras viva la aplicación.

@Configuration
public class LigasConfig {

    /**
     * Bloque externo: PROC_LEVANTA y FREEZE(CONTROL, PROC_CONTROL). En Spring el arranque
     * lo hace @PostConstruct de LigasFacade y el "congelamiento" es simplemente que el bean
     * permanece registrado en el contexto hasta el apagado.
     */
    @Bean
    LigasL039Client ligasL039Client(RestClient.Builder http, LigasProperties props) {
        return new LigasL039HttpClient(http.baseUrl(props.destinoPorOmision()).build());
    }
}
